function legacyPrologue(){enter('prologue',chapters.guild,'Opening narration · E to skip');narrationDone=false;const txt='A few centuries ago, a group of explorers wanted to find the Kingdom of Aurevullem. This kingdom was said to have treasures and secrets a person wishes to have. Countless explorers went to search for this so-called kingdom and failed. Many believed it was a myth... But I believe otherwise. My name is Velvid, and a few months ago I gathered a group of explorers to search with me. A widespread rumor was that it was at the top of the Mountain of Eldians. A lot of explorers went there and found nothing. However, no one had thought of searching underground.';let token=timerToken;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(txt);u.rate=.93;u.pitch=.94;u.onend=()=>{if(token===timerToken&&state==='prologue')startGuild()};u.onerror=()=>{if(token===timerToken&&state==='prologue')startGuild()};speechSynthesis.speak(u)}catch(e){setTimeout(()=>{if(token===timerToken&&state==='prologue')startGuild()},2500)}setTimeout(()=>{if(token===timerToken&&state==='prologue')startGuild()},40000)}
// The supplied player-made trailer is the opening cinematic. No computer voice overrides it.
const introVideo=$('introVideo'),cinematic=$('cinematic');
let cinematicActive=false,paused=false,ambientMuted=false,chapterToastTimer=0,lastChapterName='',dialogueFull='',dialogueVisible=0,dialogueTyping=false;
function beginPrologue(){
  try{speechSynthesis.cancel()}catch(e){}
  state='cinematic';cinematicActive=true;
  hide(UI.menu,UI.dialogue,UI.choice,UI.overlay,UI.hint,UI.interact);
  hud('PROLOGUE · THE LOST KINGDOM','Your cinematic opening');
  show(cinematic);
  introVideo.currentTime=0;introVideo.muted=false;
  $('cinemaMute').textContent='♪ SOUND ON';
  const started=introVideo.play();
  if(started&&started.catch) started.catch(()=>{hint('Press PLAY on the cinematic to start.');introVideo.controls=true});
}
function finishCinematic(){
  if(!cinematicActive)return;
  cinematicActive=false;introVideo.pause();introVideo.controls=false;hide(cinematic);
  startGuild();
}
introVideo.addEventListener('ended',finishCinematic);
introVideo.addEventListener('error',()=>{if(cinematicActive){hint('Could not play opening video; starting the adventure.');finishCinematic()}});
introVideo.addEventListener('timeupdate',()=>{if(introVideo.duration)$('cinemaProgressBar').style.width=((introVideo.currentTime/introVideo.duration)*100)+'%'});
$('cinemaSkip').onclick=finishCinematic;
$('cinemaMute').onclick=()=>{introVideo.muted=!introVideo.muted;$('cinemaMute').textContent=introVideo.muted?'♪ MUTED':'♪ SOUND ON'};
function notifyChapter(name){
 if(!name || name===lastChapterName||name.startsWith('PROLOGUE'))return;
 lastChapterName=name;
 $('chapterRevealName').textContent=name.replace(/^CHAPTER [IVX]+ · /,'');
 const root=$('chapterReveal');hide(root);void root.offsetWidth;show(root);
 clearTimeout(chapterToastTimer);chapterToastTimer=setTimeout(()=>hide(root),2200);
}
function togglePause(){
 if(cinematicActive)return;
 if(state==='menu')return;
 paused=!paused;$('pauseOverlay').classList.toggle('hidden',!paused);
 if(paused){hide($('chapterReveal'));}else{try{window.focus()}catch(e){}}updateAmbient();
}
$('resumeBtn').onclick=()=>{if(paused)togglePause()};
$('restartBtn').onclick=()=>location.reload();
// Generated cave/sea ambience. It begins after a deliberate user interaction and
// does not play over the user's recorded cinematic.
let soundCtx=null,ambientNodes=null,lastAmbient='',ambientUpdateAt=0;
function ambientSceneName(s){return ['sea','seaReveal','seaVisions','visions','narwhal'].includes(s)?'sea':['grave','flowers'].includes(s)?'field':['guild'].includes(s)?'guild':['chase','monsterReveal'].includes(s)?'danger':'cave'}
function createAmbient(){
 if(soundCtx||ambientMuted)return;
 try{soundCtx=new (window.AudioContext||window.webkitAudioContext)()}catch(e){}
}
function updateAmbient(){
 if(!soundCtx||ambientMuted||state==='cinematic'||paused||state==='menu'){
  if(ambientNodes)ambientNodes.gain.gain.setTargetAtTime(.00001,soundCtx.currentTime,.18);
  return;
 }
 let s=ambientSceneName(state==='dialogue'?behind:state);
 if(s===lastAmbient&&ambientNodes){ambientNodes.gain.gain.setTargetAtTime(s==='danger'?.018:s==='sea'?.021:.012,soundCtx.currentTime,.18);return;}
 lastAmbient=s;
 if(ambientNodes){ambientNodes.gain.gain.setTargetAtTime(.00001,soundCtx.currentTime,.15);try{ambientNodes.oscs.forEach(o=>o.stop(soundCtx.currentTime+.8))}catch(e){}}
 const gain=soundCtx.createGain();gain.gain.value=.0001;gain.connect(soundCtx.destination);
 const oscs=[];
 const pitch=s==='sea'?[88,132,176]:s==='field'?[174,261.6,349]:s==='guild'?[130.8,196,261.6]:s==='danger'?[52,78,104]:[65,98,130.8];
 pitch.forEach((f,i)=>{let o=soundCtx.createOscillator(),vol=soundCtx.createGain();o.type=i===0?'sine':'triangle';o.frequency.value=f;vol.gain.value=[.4,.12,.06][i];o.connect(vol);vol.connect(gain);o.start();oscs.push(o)});
 gain.gain.setTargetAtTime(s==='danger'?.018:s==='sea'?.021:.012,soundCtx.currentTime,.9);
 ambientNodes={gain,oscs};
}
