function caveTargets(){let a=[];if(!flags.cave.lamp)a.push({kind:'lamp',x:360,y:336});if(!flags.cave.wall)a.push({kind:'rock',x:575,y:345});a.push({kind:'footprints',x:790,y:369});return a}
function caveInteract(){let i=nearest(caveTargets(),105);if(!i)return;if(i.kind==='lamp'){flags.cave.lamp=true;dialogue([{text:'The cave was quiet. Nothing seemed out of the ordinary. Just cold air and weak lantern light.'}]);return}if(i.kind==='rock'){flags.cave.wall=true;dialogue([{text:'Water dripped between the rocks. A normal cave. At least, that was what I thought.'}]);return}if(!flags.cave.tracks){flags.cave.tracks=true;dialogue([{text:'Wait... footprints?'},{who:'Velvid',text:'Everyone, over here! There are footprints leading farther inside.'},{who:'Levi',text:'Someone was here before us. Let’s see where they lead.'}],()=>{hud(chapters.cave,'E · follow the footprints into the passage')})}else{transition('DEEPER UNDERGROUND',1400,enterPassage)}}
