function mazeReveal(){pos={x:280,y:347,face:1,walk:0};flags.mazeWall=false;enter('mazeReveal',chapters.cave,'Investigate the enormous wall ahead');dialogue([{text:'The passage opened into a maze. A real maze, buried beneath the mountain.'},{text:'The walls looked sixty meters tall. But how? That was impossible.'}])}
function revealInteract(){let i=nearest([{x:750,y:330,kind:'wall'},{x:125,y:351,kind:'back'}],100);if(!i)return;if(i.kind==='wall'&&!flags.mazeWall){flags.mazeWall=true;dialogue([{who:'Levi',text:'These walls... they go farther up than our lanterns can reach.'},{who:'Evelyn',text:'We should go back and get a bigger team.'},{text:'Everyone agreed to turn around.'}],()=>{hud(chapters.cave,'Return to the opening · move left')})}else if(i.kind==='back'&&flags.mazeWall){transition('THE WAY BACK',1100,missingEntrance)}}
function missingEntrance(){enter('sealed',chapters.lost,'The entrance... it disappeared');dialogue([{text:'When we went back, the entrance was gone.'},{text:'I felt my blood run cold. Nobody moved. The silence was so deafening you could hear a pin drop.'},{text:'Evelyn’s face was ash grey. Our lanterns barely lit the cave.'},{who:'Velvid',text:'The only way is to keep moving forward.'},{who:'Evelyn',text:'No! We should try going back!'},{who:'Levi',text:'No, she’s right. There’s no way out of this.'},{who:'Evelyn',text:'And if we die?!'},{who:'Levi',text:'Then we’ll at least die trying to uncover the truth.'},{text:'No one protested. I suggested we wait and take a breath. Everyone agreed.'}],()=>{pos={x:300,y:350,face:1,walk:0};enter('lostPause',chapters.lost,'Speak to the team · approach Welt')})}
function lostTalk(){dialogue([{who:'Welt',text:'Did we seriously come here expecting to come out alive and well?'},{text:'Nobody answered. Everyone knew the answer.'},{text:'The cave was cold and quiet. Ashlyn was sweating, even though it was freezing.'},{who:'Levi',text:'Let’s go. We have no time to spare.'},{who:'Aaron',text:'We should split up.'},{who:'Evelyn',text:'Hell no! Have you gone crazy?? Did you bump your head?'},{who:'Velvid',text:'You must think you’re a main character for a horror movie with your IQ.'},{who:'Aaron',text:'Pretty niche coming from you since you’re the reason we’re here.'},{text:'Everyone became tense. I felt like an idiot.'},{who:'Welt',text:'If one of us finds the exit, we leave marks and go back for the other group.'},{text:'Everyone agreed.'}],()=>splitScene())}
