function comfortAshlyn(){dialogue([{text:'I went over to comfort Ashlyn, but I had no words to say. I was just as lost as she was.'},{text:'We waved goodbye and went our separate ways.'},{text:'I know I shouldn’t be thinking this... but we’re so done for.'}],()=>{px=100;enter('mazeWalk',chapters.maze,'Move right · explore the maze')})}
function seeMonster(){enter('monsterReveal',chapters.maze,'Something is moving above you');dialogue([{text:'Astra hadn’t said a single word. The silence was broken by Evelyn’s screech.'},{text:'She was pointing at the wall. A gigantic creature was crawling down toward us.'},{who:'Evelyn',text:'RUN!'},{text:'Apparently giant spiders are NOT slow. Movies lied.'}],startChase)}
function startChase(){px=240;vY=0;jumpY=0;projectiles=[];nextShot=105;chaseHits=0;monX=-200;runTime=0;enter('chase',chapters.maze,'Escape the spider · SPACE to dodge its blasts');hint('Keep moving! The spider occasionally fires glowing webs. SPACE to jump over them.')}
function afterChase(){enter('hideVines',chapters.maze,'Hide among the vines');dialogue([{who:'Evelyn',text:'Hide! Behind those vines!'},{text:'The thing ran past us. For a moment, we could finally breathe.'},{who:'Levi',text:'I think we should take some rest. Then we’ll go.'},{who:'Evelyn',text:'No way, no way, no way! I won’t be able to sleep after what I just witnessed!'},{text:'Astra put a hand on Evelyn’s shoulder and whispered something to her. Slowly, Evelyn calmed down.'},{text:'Levi volunteered to take first watch. I suggested two people watch together.'},{text:'Astra set the trail for later, then she and Evelyn lay down on the thick vines to rest.'}],()=>startRest())}
function startRest(){restDone=false;markDone=false;pos={x:390,y:370,face:1,walk:0};enter('rest',chapters.maze,'First watch · talk to Levi')}
function restInteract(){let i=nearest([{kind:'Levi',x:605,y:350},{kind:'sleepers',x:250,y:378},{kind:'marks',x:845,y:370}],115);if(!i)return;if(i.kind==='sleepers'){dialogue([{text:'Astra and Evelyn are resting on the vines, their breathing shallow. They finally managed to fall asleep.'}]);return}if(i.kind==='Levi'){dialogue([{text:'While they rested, Levi and I kept watch and organized our supplies. We had to ration our food and water.'},{who:'Velvid',text:'Soooo uh, what do you take from all of this?'},{who:'Levi',text:'I think it’s pretty self-explanatory.'},{who:'Velvid',text:'What are you going to do after leaving this place?'},{text:'Levi looked into the distance, as though he’d never considered leaving.'},{who:'Levi',text:'Nothing if I’m being honest. I don’t have anywhere to go back to anyways.'},{who:'Levi',text:'Our shift is over. Let’s wake them up.'}],()=>{restDone=true;hud(chapters.maze,'Days later · inspect the marks on the right')});return}if(i.kind==='marks'&&restDone){dialogue([{text:'Day after day, we kept taking shifts, kept mapping out the maze.'},{text:'And then we saw it... marks left by the other team!'},{text:'We followed them, but I couldn’t shake the feeling that something was wrong.'},{text:'Then we bumped into someone.'}],reunionScene)}else if(i.kind==='marks')hint('Talk to Levi first. It is still your watch.')}
function reunionScene(){enter('reunion',chapters.reunion,'Aaron and Welt are here. Where is Ashlyn?');dialogue([{text:'It was Aaron... and Welt? But how? Who had left the trail? And where was Ashlyn?'},{text:'Astra suddenly pulled me back and pointed a knife at them.'},{who:'Evelyn',text:'What are you doing?! These are our friends!'},{who:'Levi',text:'No... this maze could be playing tricks on us.'},{who:'Astra',text:'Exactly.'},{who:'Welt',text:'Calm down.'},{who:'Astra',text:'How long have I known you for?'},{who:'Welt',text:'Five years.'},{text:'Astra stumbled on her next words. Aaron was clutching his bleeding shoulder.'},{who:'Velvid',text:'What happened to you guys?'},{who:'Welt',text:'We got attacked by some... creature. And when we woke up the next day, Ashlyn was gone.'},{who:'Evelyn',text:'Gone?! What do you mean gone?!'},{who:'Welt',text:'Gone as in the next day vanished!'},{who:'Aaron',text:'So you guys didn’t leave the trail?'},{who:'Levi',text:'No, didn’t you?'},{who:'Astra',text:'What if it was Ashlyn?'},{text:'Nobody answered.'},{who:'Velvid',text:'The only way to find out is to keep moving forward.'},{text:'Levi offered to help Aaron, but he refused.'}],()=>{pos={x:180,y:345,face:1,walk:0};enter('bloodTrail',chapters.reunion,'Follow the marks · look for Ashlyn')})}
function ashlynFound(){enter('ashlynFound',chapters.ashlyn,'Ashlyn...');dialogue([{text:'Then I smelled it... blood. So much blood.'},{text:'Ashlyn was lying on the ground, badly hurt, the stones beneath her stained dark red.'},{text:'I ran to her side before anyone could stop me. She was still crying, so surely she was alive... right?'},{text:'Blood kept slipping between the cracks in the rock. Drop after drop after drop.'},{who:'Ashlyn',text:'Life wasn’t so bad after all.'},{text:'Her breathing grew weaker. The air around us felt painfully still, as if the entire maze had stopped to listen.'},{text:'And then it stopped.'},{text:'We could not leave her there. I remembered the field of flowers we had passed, and we carried her there.'}],()=>{pos={x:365,y:362,face:1,walk:0};enter('flowers',chapters.ashlyn,'Approach the place where Ashlyn will rest')})}
function buryAshlyn(){enter('grave',chapters.ashlyn,'Seven came. Six are left.');dialogue([{text:'We closed her eyes and buried her in the field of flowers.'},{text:'We found a rock and constructed a gravestone.'},{text:'In memory of Ashlyn Grey. A daughter, an aunt, and a dear friend.'},{text:'Seven came... six are left.'}],()=>transition('SOME TIME LATER',1900,stairsScene))}
function stairsScene(){pos={x:385,y:349,face:1,walk:0};enter('stairs',chapters.stairs,'Approach the staircase');dialogue([{text:'We followed Ashlyn’s marks until the trail ended.'},{text:'There it was. The exit... or so we thought. A staircase leading downward.'}])}
function stairsTalk(){dialogue([{who:'Levi',text:'The staircase is leading downwards, which means it’s probably taking us deeper in!'},{who:'Velvid',text:'All in favor?'},{text:'Everyone raised a hand except Aaron.'},{who:'Aaron',text:'We’re not even sure what’ll happen to us! What if...'},{who:'Velvid',text:'What if what?'},{who:'Aaron',text:'What if that... thing comes back?'},{who:'Astra',text:'What thing? You have to tell us so we know what we’re up against.'},{text:'Aaron looked away.'},{who:'Astra',text:'And you, Welt? Are you going to tell us about that thing?'},{who:'Welt',text:'Well... I didn’t really see it. Only Aaron and Ashlyn saw—'},{who:'Evelyn',text:'How?!'},{who:'Welt',text:'I was going to say, before you interrupted me...'},{who:'Evelyn',text:'Sorry.'}],startFlash)}
function startFlash(){flashStep=0;enter('flash',chapters.stairs,'Welt’s memory · E to continue');flashNext()}
const flashLines=[[{who:'Welt',text:'We took turns scouting for about an hour at a time. I was the one who went ahead.'}],[{text:'I left Aaron and Ashlyn at our camp and walked deeper into the tunnels alone.'},{text:'It was too quiet. Even my own footsteps sounded wrong.'}],[{who:'Welt',text:'When I came back, the camp was ruined. Aaron and Ashlyn were gone.'}],[{text:'The lanterns were scattered. Supplies had been torn across the stones as if something had ripped straight through the camp.'},{text:'There was blood on the ground... and marks leading into the dark.'}],[{text:'I followed the trail, but before I could go far, I heard movement behind me.'},{text:'Aaron stumbled back first. Ashlyn came after him, shaken and barely able to speak.'}],[{who:'Welt',text:'Neither of them could explain it properly at first. They were terrified.'},{who:'Welt',text:'Ashlyn said the creature could bring nightmares to life.'}],[{text:'Even now, I can still remember the look on her face when she said it.'}]];
function flashNext(){if(flashStep<flashLines.length){let index=flashStep++;dialogue(flashLines[index],()=>{state='flash';hud(chapters.stairs,'Welt’s memory · E to continue')})}else{enter('stairs',chapters.stairs,'Descend the staircase');dialogue([{who:'Levi',text:'Aaron, how’s your shoulder?'},{who:'Velvid',text:'Oh yeah. How is it?'},{who:'Aaron',text:'Fine.'},{text:'Somehow I knew it wasn’t. The others seemed to know too.'}],()=>choice('The staircase leads deeper underground.',[{text:'Stay together and descend carefully',fn:()=>{flags.seaApproach='together';seaReveal()}},{text:'Check everyone’s lanterns before descending',fn:()=>{flags.seaApproach='prepared';seaReveal()}}]))}}
function seaReveal(){enter('seaReveal',chapters.sea,'The sea beneath the mountain');dialogue([{text:'We went down the stairs. What we saw shocked us.'},{text:'It was a... sea? No. More like an underwater cave. It glowed as bright as the moon.'},{who:'Velvid',text:'What...'},{text:'Astra looked amused, afraid, and desperate all at once. Welt’s eyes seemed to glow.'},{who:'Welt',text:'Look!'},{text:'Two boats approached us. No one was driving them.'},{who:'Evelyn',text:'No, no, no, no! We are NOT getting—'},{who:'Welt',text:'We are. It’s our only chance of getting out.'},{who:'Astra',text:'It’s... a sea?'},{who:'Velvid',text:'And just across that sea, the treasure of freedom. Waiting for us.'},{who:'Levi',text:'Me, Velvid and Aaron in one boat. The rest in the other.'},{text:'I felt like this would end badly. But who cares what I think?'},{text:flags.seaApproach==='prepared'?'We checked every lantern before boarding. Then we divided the gear and said goodbye.':'We divided the gear and said goodbye. Who knew how many of us would still be breathing after this?'}],()=>{boat={x:430,y:447};seaDistance=0;enter('sea',chapters.sea,'Steer your boat upward · WASD / arrows')})}
function visionsScene(){enter('visions',chapters.visions,'Reflections in the water');dialogue([{text:'We had been boating in silence for about thirty minutes.'},{who:'Velvid',text:'Are you sure you can’t tell us anything about that thing? Not even a littleeeee bit?'},{who:'Aaron',text:'You don’t say anything for about an hour and this is what you ask?'},{text:'I immediately felt terrible. I looked down at my shoes.'},{who:'Aaron',text:'Well... it had knives as hands and it could... No, I must’ve imagined that.'},{who:'Aaron',text:'I see Astra in the water!!'},{who:'Velvid',text:'Are you sure you haven’t gone bonkers?'},{who:'Aaron',text:'No! Come here and see!'},{text:'I looked over the edge. I saw my childhood house... and myself standing beside it.'},{who:'Velvid',text:'I see something else. Me, standing beside my old house.'},{who:'Levi',text:'You must be seeing Astra because she’s your kin.'},{who:'Velvid',text:'What do you see?'},{who:'Levi',text:'Me sitting on a branch of a tree.'},{who:'Aaron',text:'Are we gonna address the constellation or have I really gone bonkers?'},{who:'Levi',text:'You know I actually might’ve gone completely bonkers as well.'},{who:'Velvid',text:'I need a break.'},{who:'Aaron',text:'Do you believe any of us are going to make it out of this?'},{who:'Velvid',text:'We have to.'},{text:'Suddenly a piercing noise caught us so off guard we nearly fell into the sea.'}],()=>{enter('seaVisions',chapters.visions,'Continue forward through the glowing water');boat={x:430,y:440};seaDistance=0})}
function narwhalScene(){enter('narwhal',chapters.narwhal,'An impossible visitor');dialogue([{text:'It was a narwhal. All the way down here?!'},{text:'It seemed friendly... but I couldn’t trust anything after the maze.'},{who:'Levi',text:'How did a narwhal end up in an underwater cave?'},{who:'Velvid',text:'You’re asking me? You’re the professional.'},{who:'Aaron',text:'Let’s call it Sir Neighs-a-Lot.'},{who:'Velvid',text:'No. We’re not naming it. It could be hostile, and we don’t know what’ll happen if it sti—'},{text:'The boat suddenly stopped. I fell flat on my face.'},{who:'Velvid',text:'How?!'},{who:'Aaron',text:'Karma is a restaurant, you know. You get served what you deserve.'}],()=>{enter('cliffhanger',chapters.narwhal,'The story continues when the next chapters are written');UI.menu.innerHTML='<div class="logo" style="font-size:clamp(30px,4.4vw,55px)">TO BE CONTINUED</div><div class="subtitle">The boat has stopped. What happens next?</div><button id="again">PLAY AGAIN</button><div class="credits">The manuscript currently ends here. Levels 3–5 and true branching endings are intentionally unwritten.</div>';show(UI.menu);$('again').onclick=()=>location.reload()})}
