function haze(x,y,r,col){let grad=g.createRadialGradient(x,y,3,x,y,r);grad.addColorStop(0,col);grad.addColorStop(1,'#00000000');g.fillStyle=grad;g.fillRect(x-r,y-r,r*2,r*2)}
function stonePattern(seed=0,yTop=80,bottom=424,c1='#293e48',c2='#42515a'){for(let j=0;j<8;j++)for(let i=0;i<22;i++){let xx=i*49+(j%2)*24,yy=yTop+j*((bottom-yTop)/8),vv=rand(seed+i*8+j*49);R(xx,yy,46,2,vv>.5?c1:c2);if(vv>.54)R(xx+3,yy+10,3,12,c1);if(vv>.76)R(xx+27,yy+23,12,3,c2)}}
function particles(count=35,palette=['#b9cdb4','#e7d4a8']){for(let i=0;i<count;i++){let xx=(rand(i*12+12)*960+Math.sin(tickNo*.005+i)*19+960)%960,yy=(rand(i*34+60)*520+tickNo*(i%4+1)*.06)%540;R(xx,yy,2+(i%3===0?1:0),2,palette[i%palette.length])}}
function lantern(x,y,bright=true){R(x-6,y-6,24,44,'#26333a');R(x-3,y-1,18,29,'#bca67e');R(x+1,y+3,10,22,'#f8d59b');R(x+4,y-8,5,4,'#e4d5b4');R(x-9,y+39,30,4,'#1c2832');if(bright)haze(x+7,y+18,120,'#ffc9703f')}
