function caveArt(){caveBackdrop();haze(250,245,245,'#a8c9c12d');arch(22,207,189,215,'#1b303d');R(802,155,122,266,'#172936');R(815,168,96,247,'#0d1c29');footprints();lantern(356,305);for(let i=0;i<5;i++)sprite(['Astra','Levi','Evelyn','Aaron','Welt'][i],245+i*105,416,2.45,0,1);sprite('Ashlyn',790,414,2.45,0,-1);sprite('Velvid',pos.x,pos.y+45,2.75,pos.walk,pos.face);T('THE CAVE UNDER THE MOUNTAIN',480,103,26,'#e4e3d5','center');prompt(nearest(caveTargets(),105),!flags.cave.tracks?'Investigate':flags.cave.tracks?'Follow the footprints':'Investigate')}
function passageArt(){caveBackdrop(false,px);for(let i=0;i<7;i++){let x=(i*198-px*.58)%1320;if(x<-80)x+=1320;arch(x,170,92,249,'#213541')}footprints(px*.1);lantern(703,290);for(let i=0;i<6;i++)sprite(['Astra','Levi','Evelyn','Aaron','Welt','Ashlyn'][i],215+i*104,415,2.5,Math.sin(tickNo/15),1);sprite('Velvid',pos.x||230,400,2.7,Math.sin(tickNo/11),1);T('FOLLOW THE FOOTPRINTS →',478,121,24,'#e5dcc3','center')}
