// Filmic finishing pass: calibrated vignette, drifting dust, reactive glow and edge framing.
function cinematicAtmosphere(active){
 if(['menu','prologue','transition','cliffhanger'].includes(active))return;
 g.save();
 // A very light warm/cool grade ties the hand-painted environments together.
 const isSea=['sea','seaReveal','seaVisions','visions','narwhal'].includes(active);
 const isField=['flowers','grave'].includes(active);
 let tint=g.createLinearGradient(0,0,W,H);
 tint.addColorStop(0,isSea?'#77ddde0c':isField?'#edc6a40e':'#b4c5cb06');
 tint.addColorStop(1,isSea?'#080c2315':isField?'#53321f09':'#05081816');
 g.fillStyle=tint;g.fillRect(0,0,W,H);
 let num=isSea?19:isField?27:15;
 for(let i=0;i<num;i++){
   let a=rand(i*73+33),b=rand(i*29+42);
   let xx=(a*W+tickNo*(i%3+1)*.095)%W;
   let yy=(b*H+Math.sin(tickNo*.015+i)*11+H)%H;
   const size=(i%5===0?2.4:1.2);
   g.globalAlpha=(isSea?.35:.20)+Math.sin(tickNo*.016+i)*.08;
   g.fillStyle=isSea?'#d2f7ed':isField?'#fbeac2':'#d7d2bf';
   g.fillRect(xx,yy,size,size);
 }
 g.globalAlpha=1;
 const grad=g.createRadialGradient(W/2,H/2,140,W/2,H/2,640);
 grad.addColorStop(0,'#00000000');grad.addColorStop(1,'#05071050');
 g.fillStyle=grad;g.fillRect(0,0,W,H);
 // Engraved inset marks — visual framing without blocking movement.
 g.strokeStyle='#b8a37d33';g.lineWidth=1;
 [[18,18,1,1],[W-18,18,-1,1],[18,H-18,1,-1],[W-18,H-18,-1,-1]].forEach(([x,y,sx,sy])=>{g.beginPath();g.moveTo(x,y+sy*18);g.lineTo(x,y);g.lineTo(x+sx*18,y);g.stroke()});
 g.restore();
}
function drawWorld(){g.clearRect(0,0,W,H);let active=state==='dialogue'||state==='choice'?behind:state;hide(UI.interact);switch(active){case'menu':case'prologue':case'cliffhanger':{if(introImage.complete&&introImage.naturalWidth){g.drawImage(introImage,0,0,W,H)}else{caveBackdrop(true)}if(active!=='menu')R(0,0,W,H,'#0615207f');if(active==='prologue'){T('A VOICE FROM A FORGOTTEN CENTURY...',480,448,26,'#fff0cf','center');T('E · SKIP NARRATION',480,493,17,'#c8cabe','center')}break}case'guild':guildBackground();break;case'cave':caveArt();break;case'passage':passageArt();break;case'mazeReveal':mazeEntranceArt();break;case'sealed':sealedArt();break;case'lostPause':lostArt();break;case'split':splitArt();break;case'mazeWalk':mazeArt();break;case'monsterReveal':monsterRevealArt();break;case'chase':chaseArt();break;case'hideVines':vineArt();break;case'rest':restArt();break;case'reunion':reunionArt();break;case'bloodTrail':trailArt();break;case'ashlynFound':ashlynArt();break;case'flowers':flowersArt();break;case'grave':graveArt();break;case'stairs':stairsArt();break;case'flash':flashArt();break;case'seaReveal':seaRevealArt();break;case'sea':case'seaVisions':seaArt();break;case'visions':visionArt();break;case'narwhal':narwhalArt();break;case'transition':R(0,0,W,H,'#081724');break;default:caveBackdrop(true)}
if(state==='dialogue'||state==='choice')hide(UI.interact);cinematicAtmosphere(active)}
function movement(){const dx=Number(!!(keys.KeyD||keys.ArrowRight))-Number(!!(keys.KeyA||keys.ArrowLeft)),dy=Number(!!(keys.KeyS||keys.ArrowDown))-Number(!!(keys.KeyW||keys.ArrowUp));if(!dx&&!dy)return;const sp=3/Math.hypot(dx,dy);pos.x=Math.min(888,Math.max(75,pos.x+dx*sp));pos.y=Math.min(391,Math.max(225,pos.y+dy*sp));pos.walk+=.7;if(dx)pos.face=dx>0?1:-1}
function update(delta){if(paused)return;if(tickNo-ambientUpdateAt>30){ambientUpdateAt=tickNo;updateAmbient();}if(state==='dialogue'&&dialogueTyping){dialogueVisible=Math.min(dialogueFull.length,dialogueVisible+Math.max(1,Math.floor(delta/15)));UI.storyText.textContent=dialogueFull.slice(0,dialogueVisible);if(dialogueVisible>=dialogueFull.length)dialogueTyping=false;}tickNo+=Math.min(delta,35)/16.66;worldTime+=delta;if(['guild','cave','mazeReveal','split','rest','bloodTrail','flowers','stairs','lostPause'].includes(state))movement();if(state==='passage'){px+=Math.max(0,Number(!!(keys.KeyD||keys.ArrowRight)))*4.1;pos.x=225;if(px>1100)mazeReveal()}
if(state==='mazeWalk'){px+=Math.max(0,Number(!!(keys.KeyD||keys.ArrowRight)))*4.8;px-=Math.max(0,Number(!!(keys.KeyA||keys.ArrowLeft)))*2.0;px=Math.max(0,px);if(px>1160)seeMonster()}
if(state==='chase'){
 const frames=Math.min(delta,35)/16.66;
 runTime+=frames;
 let right=Number(!!(keys.KeyD||keys.ArrowRight)),left=Number(!!(keys.KeyA||keys.ArrowLeft));
 // Velvid moves forward automatically. Holding right speeds her up.
 px+=(2.85+right*3.2-left*.8)*frames;
 jumpY+=vY*frames;vY+=.57*frames;
 if(jumpY>0){jumpY=0;vY=0}
 // The monster only attacks occasionally, with a long break between shots.
 if(runTime>=nextShot){projectiles.push({x:148,hit:false});nextShot=runTime+165+Math.floor(rand(Math.floor(runTime))*35);hint('Glowing web incoming! Press SPACE to jump.');}
 for(let i=projectiles.length-1;i>=0;i--){let shot=projectiles[i];shot.x+=3.1*frames;
   if(Math.abs(shot.x-340)<18&&jumpY>-34&&!shot.hit){shot.hit=true;px=Math.max(240,px-65);chaseHits++;hint('A web grazed you! Keep running — you can still escape.');}
   if(shot.x>W+40||shot.hit)projectiles.splice(i,1);
 }
 if(px>3250)afterChase();
}
if(state==='bloodTrail'){if(pos.x>812)ashlynFound()}
if(state==='sea'||state==='seaVisions'){let dx=Number(!!(keys.KeyD||keys.ArrowRight))-Number(!!(keys.KeyA||keys.ArrowLeft)),dy=Number(!!(keys.KeyS||keys.ArrowDown))-Number(!!(keys.KeyW||keys.ArrowUp));boat.x=Math.max(100,Math.min(865,boat.x+dx*3.5));boat.y=Math.max(90,Math.min(475,boat.y+dy*3.5));seaDistance+=Math.max(0,-dy)*2.3;if(seaDistance>260){if(state==='sea')visionsScene();else narwhalScene()}}
}
function interact(){switch(state){case'guild':guildInteract();break;case'cave':caveInteract();break;case'mazeReveal':revealInteract();break;case'lostPause':if(D(pos.x,pos.y,620,345)<255)lostTalk();else hint('Go over to Welt and the group.');break;case'split':if(D(pos.x,pos.y,820,352)<160)comfortAshlyn();else hint('Ashlyn is waiting at the other end of the passage.');break;case'rest':restInteract();break;case'flowers':if(D(pos.x,pos.y,650,353)<145)buryAshlyn();break;case'stairs':if(D(pos.x,pos.y,478,345)<275)stairsTalk();break;case'flash':flashNext();break}}
function keydown(e){if(['Space','ArrowDown','ArrowUp','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(state==='cinematic'){if(e.code==='Escape'||e.code==='Enter'||e.code==='KeyE'){finishCinematic()}return}if(e.code==='Escape'&&state!=='menu'){togglePause();return}if(e.code==='KeyM'){ambientMuted=!ambientMuted;updateAmbient();hint(ambientMuted?'Atmosphere muted':'Atmosphere enabled');return}if(paused)return;if(e.code==='Space'&&state==='chase'&&jumpY===0){vY=-11.3;jumpY=-1;return}if(state==='choice'&&/^Digit[1-9]$/.test(e.code)){let b=UI.choiceList.children[+e.code.slice(-1)-1];b?.click();return}if(e.code==='KeyE'||e.code==='Enter'){if(state==='dialogue')nextDialogue();else if(state==='prologue')startGuild();else if(state==='flash')flashNext();else interact()}}
window.addEventListener('keydown',keydown);window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{for(let k in keys)keys[k]=false});UI.dialogue.addEventListener('click',nextDialogue);
$('newGame').onclick=()=>{createAmbient();beginPrologue()};$('skipPrologue').onclick=()=>{createAmbient();startGuild()};
function loop(t){let delta=Math.min(40,t-(loop.last||t));loop.last=t;update(delta);drawWorld();requestAnimationFrame(loop)}requestAnimationFrame(loop);
